CREATE TABLE IF NOT EXISTS sources (id BIGSERIAL PRIMARY KEY, source_key TEXT UNIQUE NOT NULL, institution TEXT, homepage TEXT, record_url TEXT, api_url TEXT, rights TEXT, image_policy TEXT, retrieved_at TIMESTAMPTZ, content_sha256 TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS periods (id BIGSERIAL PRIMARY KEY, period_key TEXT UNIQUE NOT NULL, name TEXT NOT NULL, parent_id BIGINT REFERENCES periods(id), start_year INT, end_year INT, notes TEXT);
CREATE TABLE IF NOT EXISTS objects (id BIGSERIAL PRIMARY KEY, external_id TEXT UNIQUE, title TEXT NOT NULL, period_id BIGINT REFERENCES periods(id), object_type TEXT, culture TEXT, script TEXT, date_from INT, date_to INT, site TEXT, material TEXT, description TEXT, source_id BIGINT REFERENCES sources(id), image_url TEXT, rights TEXT, provenance TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS readings (id BIGSERIAL PRIMARY KEY, object_id BIGINT REFERENCES objects(id) ON DELETE CASCADE, reading_type TEXT NOT NULL, transliteration TEXT, arabic_interpretation TEXT, english_interpretation TEXT, reviewer TEXT, confidence DOUBLE PRECISION CHECK(confidence BETWEEN 0 AND 1), status TEXT DEFAULT 'candidate', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS annotations (id BIGSERIAL PRIMARY KEY, object_id BIGINT REFERENCES objects(id) ON DELETE CASCADE, x1 DOUBLE PRECISION, y1 DOUBLE PRECISION, x2 DOUBLE PRECISION, y2 DOUBLE PRECISION, glyph_candidate TEXT, transliteration_candidate TEXT, confidence DOUBLE PRECISION CHECK(confidence BETWEEN 0 AND 1), reviewer TEXT, status TEXT DEFAULT 'candidate', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS translation_results (id BIGSERIAL PRIMARY KEY, object_id BIGINT REFERENCES objects(id) ON DELETE SET NULL, source_language TEXT NOT NULL, target_language TEXT NOT NULL, source_text TEXT NOT NULL, mode TEXT NOT NULL, output TEXT, confidence DOUBLE PRECISION, alternatives_json JSONB DEFAULT '[]', proof_notes_json JSONB DEFAULT '[]', provenance_json JSONB DEFAULT '{}', review_required BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS chatbot_sessions (id TEXT PRIMARY KEY, provider TEXT NOT NULL, model TEXT, evidence_json JSONB DEFAULT '[]', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
